sp_widget.client_script:
api.controller = function($scope, $window) {
  var c = this;
  c.currentFilter = 'ALL';
  c.searchQuery = '';

  c.setFilter = function(filter) {
    c.currentFilter = filter;
  };

  c.filterNotifications = function(item) {
    var matchesFilter = true;
    if (c.currentFilter === 'Unread') matchesFilter = !item.read;
    else if (c.currentFilter === 'Urgent') matchesFilter = (item.priority === 'Urgent');
    else if (c.currentFilter === 'SEVIS') matchesFilter = (item.category === 'SEVIS' || item.category === 'Policy');

    if (!matchesFilter) return false;

    if (!c.searchQuery) return true;
    var q = c.searchQuery.toLowerCase();
    return (
      (item.title && item.title.toLowerCase().indexOf(q) !== -1) ||
      (item.description && item.description.toLowerCase().indexOf(q) !== -1) ||
      (item.student_name && item.student_name.toLowerCase().indexOf(q) !== -1) ||
      (item.student_id && item.student_id.toLowerCase().indexOf(q) !== -1)
    );
  };

  c.getUnreadCount = function() {
    if (!c.data.notifications) return 0;
    return c.data.notifications.filter(function(n) { return !n.read; }).length;
  };

  c.getUnreadUrgentCount = function() {
    if (!c.data.notifications) return 0;
    return c.data.notifications.filter(function(n) { return !n.read && n.priority === 'Urgent'; }).length;
  };

  c.getAiFlagCount = function() {
    if (!c.data.notifications) return 0;
    return c.data.notifications.filter(function(n) { return n.type === 'AI'; }).length;
  };

  c.toggleRead = function(item) {
    item.read = !item.read;
  };

  c.markAllRead = function() {
    if (c.data.notifications) {
      c.data.notifications.forEach(function(n) { n.read = true; });
    }
  };

  c.takeAction = function(item) {
    $window.alert("Opening case workflow for: " + item.title + " (" + (item.case_id || item.student_name) + ")");
  };
};

sp_widget.css:
.vg-workspace-container {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  color: #2b3674;
  padding: 10px;

  /* Hero Banner */
  .vg-hero-banner {
    background: linear-gradient(135deg, #091e3a 0%, #0d3a78 100%);
    border-radius: 12px;
    padding: 24px 30px;
    color: #ffffff;
    display: flex;
    justify-content: space-between;
    align-items: center;
    box-shadow: 0 8px 20px rgba(9, 30, 58, 0.15);
    margin-bottom: 24px;

    .hero-content {
      h2 {
        margin: 0 0 6px 0;
        font-weight: 700;
        font-size: 24px;
        color: #ffffff;
      }
      p {
        margin: 0;
        font-size: 13px;
        opacity: 0.85;
      }
    }

    .btn-hero-outline {
      border: 1px solid rgba(255, 255, 255, 0.4);
      background: rgba(255, 255, 255, 0.08);
      color: #ffffff;
      font-weight: 600;
      font-size: 13px;
      padding: 8px 18px;
      border-radius: 8px;
      transition: all 0.2s ease;

      &:hover {
        background: #ffffff;
        color: #0d3a78;
      }
    }
  }

  /* Metric Cards Row */
  .metric-row {
    margin-bottom: 24px;
  }

  .vg-metric-card {
    background: #ffffff;
    border-radius: 12px;
    padding: 18px 20px;
    display: flex;
    align-items: center;
    gap: 16px;
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.03);
    border: 1px solid #eef2f7;

    .metric-icon {
      width: 52px;
      height: 52px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 20px;
      flex-shrink: 0;

      &.blue-circle { background: #e8f0fe; color: #0066ff; }
      &.orange-circle { background: #fef3d6; color: #ff9f43; }
      &.green-circle { background: #e6f4ea; color: #00b074; }
      &.red-circle { background: #fde8e8; color: #ea5455; }
    }

    .metric-data {
      display: flex;
      flex-direction: column;

      .metric-number {
        font-size: 24px;
        font-weight: 700;
        line-height: 1.1;
        margin-bottom: 3px;
      }

      .metric-label {
        font-size: 11px;
        font-weight: 700;
        letter-spacing: 0.5px;
        color: #8f9bba;
        text-transform: uppercase;
        margin-bottom: 3px;
      }

      .metric-subtext {
        font-size: 11px;
        font-weight: 600;
      }
    }
  }

  /* Colors */
  .text-blue { color: #0066ff; }
  .text-orange { color: #ff9f43; }
  .text-green { color: #00b074; }
  .text-red { color: #ea5455; }

  /* Main Card Container */
  .vg-card {
    background: #ffffff;
    border-radius: 12px;
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.03);
    border: 1px solid #eef2f7;
    padding: 20px 24px;

    .vg-card-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding-bottom: 16px;
      border-bottom: 1px solid #f0f3f8;
      margin-bottom: 16px;
      flex-wrap: wrap;
      gap: 12px;

      h4 {
        margin: 0;
        font-size: 16px;
        font-weight: 700;
        color: #1b2559;

        i {
          color: #0066ff;
          margin-right: 8px;
        }
      }

      .header-right {
        display: flex;
        align-items: center;
        gap: 12px;
      }

      .filter-pills {
        background: #f4f7fe;
        padding: 3px;
        border-radius: 8px;

        .btn {
          border: none;
          background: transparent;
          color: #8f9bba;
          font-weight: 600;
          font-size: 12px;
          border-radius: 6px;
          padding: 5px 12px;

          &.active {
            background: #ffffff;
            color: #0066ff;
            box-shadow: 0 2px 6px rgba(0,0,0,0.06);
          }
        }
      }

      .search-wrapper {
        position: relative;

        .search-icon {
          position: absolute;
          left: 10px;
          top: 9px;
          color: #8f9bba;
          font-size: 12px;
        }

        .search-input {
          padding-left: 28px;
          border-radius: 8px;
          border: 1px solid #e0e5f2;
          background: #f4f7fe;
          font-size: 12px;
          width: 230px;

          &:focus {
            background: #ffffff;
            border-color: #0066ff;
          }
        }
      }
    }
  }

  /* Notifications Feed */
  .notifications-feed {
    display: flex;
    flex-direction: column;
    gap: 12px;
  }

  .notification-item {
    display: flex;
    align-items: flex-start;
    padding: 16px 20px;
    border-radius: 10px;
    background: #ffffff;
    border: 1px solid #f0f3f8;
    transition: all 0.2s ease;
    position: relative;

    &:hover {
      background: #fafcff;
      border-color: #d6e4ff;
    }

    &.is-unread {
      background: #f8faff;
      border-left: 4px solid #0066ff;
    }

    &.border-urgent {
      border-left: 4px solid #ea5455;
    }

    .notif-icon-col {
      margin-right: 16px;
      flex-shrink: 0;

      .notif-badge-icon {
        width: 42px;
        height: 42px;
        border-radius: 50%;
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 16px;

        &.badge-red { background: #fde8e8; color: #ea5455; }
        &.badge-orange { background: #fef3d6; color: #ff9f43; }
        &.badge-blue { background: #e8f0fe; color: #0066ff; }
        &.badge-green { background: #e6f4ea; color: #00b074; }
      }
    }

    .notif-body-col {
      flex-grow: 1;

      .notif-title-row {
        margin-bottom: 4px;

        .notif-title {
          font-weight: 700;
          font-size: 14px;
          color: #1b2559;
          margin-right: 8px;
        }

        .notif-type-tag {
          font-size: 11px;
          font-weight: 600;
          background: #f4f7fe;
          color: #4318ff;
          padding: 2px 8px;
          border-radius: 4px;
          margin-right: 8px;
        }

        .unread-dot {
          display: inline-block;
          width: 8px;
          height: 8px;
          border-radius: 50%;
          background: #0066ff;
        }

        .notif-time {
          font-size: 12px;
          color: #8f9bba;
        }
      }

      .notif-description {
        margin: 4px 0 8px 0;
        font-size: 13px;
        color: #4a5568;
        line-height: 1.4;
      }

      .notif-meta-row {
        display: flex;
        gap: 16px;
        font-size: 12px;
        color: #8f9bba;

        i { margin-right: 4px; }
        strong { color: #1b2559; }
      }
    }

    .notif-action-col {
      display: flex;
      align-items: center;
      gap: 8px;
      margin-left: 16px;
      flex-shrink: 0;

      .btn-review {
        background: #f4f7fe;
        color: #0066ff;
        font-weight: 600;
        border: 1px solid #e0e5f2;
        border-radius: 6px;
        padding: 5px 12px;
        font-size: 12px;

        &:hover {
          background: #0066ff;
          color: #ffffff;
        }
      }

      .btn-toggle-read {
        background: transparent;
        border: none;
        color: #8f9bba;
        font-size: 14px;
        padding: 5px;

        &:hover {
          color: #1b2559;
        }
      }
    }
  }

  .pad-lg {
    padding: 30px !important;
  }
}
